create or replace function public.get_court_occupied_ranges(p_court_id uuid,p_window_start timestamptz,p_window_end timestamptz) returns table(start_at timestamptz,end_at timestamptz) language sql stable security definer set search_path=public as $$select b.start_at,b.end_at from public.bookings b where b.court_id=p_court_id and b.status in('confirmed','pending_payment') and (b.status='confirmed' or b.hold_expires_at>now()) and b.start_at<p_window_end and b.end_at>p_window_start union all select x.start_at,x.end_at from public.blocked_times x where (x.court_id=p_court_id or x.court_id is null) and x.start_at<p_window_end and x.end_at>p_window_start$$;revoke all on function public.get_court_occupied_ranges(uuid,timestamptz,timestamptz) from public;grant execute on function public.get_court_occupied_ranges(uuid,timestamptz,timestamptz) to anon,authenticated;